def minimumXORSum(nums1: list[int], nums2: list[int]) -> int:
    n = len(nums1)
    memo = {}
    def dfs(i, mask):
        if i == n: return 0
        if mask in memo: return memo[mask]
        ans = float('inf')
        for j in range(n):
            if not (mask & (1 << j)):
                ans = min(ans, (nums1[i] ^ nums2[j]) + dfs(i + 1, mask | (1 << j)))
        memo[mask] = ans
        return ans
    return dfs(0, 0)

